add_action( 'woocommerce_shop_loop', 'perfectpixel_promo_after_nth_product' );

function perfectpixel_promo_after_nth_product() {
	// 'loop' = number of products already printed on this page.
	if ( (int) wc_get_loop_prop( 'loop' ) !== max( 1, (int) '{{promo_after_position}}' ) || ! wc_get_loop_prop( 'is_paginated' ) ) {
		return;
	}
	echo '<li class="product perfectpixel-promo" style="display:flex;align-items:center;justify-content:center;text-align:center;padding:1.5em;background:#f6f7f7">' . wp_kses_post( '{{promo_block_html}}' ) . '</li>';
}
